// Website knowledge base of the assistant: questions about using THIS site, each answered from its actual
// features (checked against the code when written; update an answer whenever the feature changes).
//
// Entry: { id, cat, k: keywords (any language; matched after Arabic normalisation, see core/conversation.js),
//          q: { ar, en }, a: { ar, en }, go?: what the button opens, subject?: for follow-up questions }
// `go`: { route } a page · { dialog } a dialog · { lesson } a lesson · { run: 'theme'|'language'|'tasbih' }
// Spanish and French visitors get the English answer (with a note) until those translations are added.
//
// To add a question: append an entry with a new id. Keep ids stable (tests and the conversation context use them).

const e = (id, cat, subject, k, q, a, go = null) => ({ id, cat, subject, k, q: { ar: q[0], en: q[1] }, a: { ar: a[0], en: a[1] }, go });

